// ─────────────────────────────────────────────────────────────────────────
//  02 · boxed counts: missing keys and == on Integer                 ★★☆
//  concepts: unboxing null · Integer cache · Objects.equals
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Sum of stock for each sku; a missing sku counts as 0. */
    static int totalQuantity(Map<String, Integer> stock, List<String> skus) {
        int total = 0;
        for (String sku : skus) {
            total += stock.getOrDefault(sku, 0);
        }
        return total;
    }

    /** True when both are null or both hold the same value. */
    static boolean sameCount(Integer a, Integer b) {
        return Objects.equals(a, b);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("present skus are summed", () ->
            eq(totalQuantity(Map.of("pen", 4, "ink", 3), List.of("pen", "ink")), 7));
        test("a missing sku counts as 0 instead of throwing (boundary)", () ->
            eq(totalQuantity(Map.of("pen", 4), List.of("pen", "pad")), 4));
        test("sameCount(1000, 1000) is true", () ->
            ok(sameCount(1000, 1000), "two boxed 1000s hold the same count"));
        test("sameCount(127, 128) is false", () ->
            ok(!sameCount(127, 128), "different counts"));
        test("two nulls are the same (unknown == unknown)", () ->
            ok(sameCount(null, null), "both unknown"));
        test("null and 5 differ, in either order", () ->
            ok(!sameCount(null, 5) && !sameCount(5, null), "unknown is not 5"));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
